/**
 * Tests getting the last modified time of a file.
 */
@Test
public void testGetLastModifiedFileInexactMatch() throws IOException {
    final String fileName = "file1.txt";
    getFileSystem().getFileSystemManager().getFilesCache().clear(getFileSystem());
    final FileObject readFolder = getReadFolder();
    final FileObject fileObject = readFolder.resolveFile(fileName);
    final long lastModifiedTimeMillis = fileObject.getContent().getLastModifiedTime();
    // now try to match
    final long lastModTimeAccuracyMillis = (long) readFolder.getFileSystem().getLastModTimeAccuracy();
    final FileTime lastModifiedTime = Files.getLastModifiedTime(Paths.get(getTestDirectory(), AbstractTestSuite.READ_TESTS_FOLDER, fileName));
    assertDeltaMillis("getLastModified on File", lastModifiedTime.toMillis(), lastModifiedTimeMillis, Math.max(lastModTimeAccuracyMillis, Duration.ofMinutes(1).toMillis()));
}

/**
 * Tests getting the last modified time of a file.
 */
@Test
public void testGetLastModifiedFileExactMatch() throws IOException {
    final String fileName = "file1.txt";
    final FileObject readFolder = getReadFolder();
    final FileObject fileObject = readFolder.resolveFile(fileName);
    final long lastModifiedTimeMillis = fileObject.getContent().getLastModifiedTime();
    // now try to match
    final FileTime lastModifiedTime = Files.getLastModifiedTime(Paths.get(getTestDirectory(), AbstractTestSuite.READ_TESTS_FOLDER, fileName));
    if (SystemUtils.IS_JAVA_1_8) {
        // Workaround OpenJDK 8 and 9 bug JDK-8177809
        // https://bugs.openjdk.java.net/browse/JDK-8177809
        assertDeltaMillis(fileName, lastModifiedTimeMillis, lastModifiedTimeMillis, lastModifiedTimeMillis);
    } else {
        assertEqualMillis("getLastModified on " + fileObject, lastModifiedTime.toMillis(), lastModifiedTimeMillis);
    }
}

